	// Attenuation = 1.0f / (factor0 + (d * factor1) + (d*d * factor2))\n	// For some reason, factor0 is set to 0.0f while factor1 is set to 1.0f/lightrange (on both D3D and OpenGL)\n	// This'll result in no visible falloff as 1.0f / (d / lightrange) will always be larger than 1.0f (if the vertex is within range)\n	\n		atten = 1.0 / (veclen / posrange.w);\n		if (veclen > posrange.w)\n		{\n			atten = 0.0;\n		}	\n#else\n		atten = clamp( (1.0 - (veclen / posrange.w)), 0.0, 1.0);		// storing 1.0f/range instead would save a rcp\n#endif\n	}\n	float dotresult = dot(ws_normal, diffvec);\n	dotresult = max(0.0, dotresult);\n\n	return dotresult * atten * diffusecol;\n}\n\nvec4 DoLighting(vec4 vertexcolour, vec4 objectspacepos, vec3 objectspacenormal)\n{\n	if (gm_LightingEnabled)\n	{\n		// Normally we'd have the light positions\\directions back-transformed from world to object space\n		// But to keep things simple for the moment we'll just transform the normal to world space\n		vec4 objectspacenormal4 = vec4(objectspacenormal, 0.0);\n		vec3 ws_normal;\n		ws_normal = (gm_Matrices[MATRIX_WORLD] * objectspacenormal4).xyz;\n		ws_normal = normalize(ws_normal);\n\n		vec3 ws_pos;\n		ws_pos = (gm_Matrices[MATRIX_WORLD] * objectspacepos).xyz;\n\n		// Accumulate lighting from different light types\n		vec4 accumcol = vec4(0.0, 0.0, 0.0, 0.0);		\n		for(int i = 0; i < MAX_VS_LIGHTS; i++)\n		{\n			accumcol += DoDirLight(ws_normal, gm_Lights_Direction[i], gm_Lights_Colour[i]);\n		}\n\n		for(int i = 0; i < MAX_VS_LIGHTS; i++)\n		{\n			accumcol += DoPointLight(ws_pos, ws_normal, gm_Lights_PosRange[i], gm_Lights_Colour[i]);\n		}\n\n		accumcol *= vertexcolour;\n		accumcol += gm_AmbientColour;\n		accumcol = min(vec4(1.0, 1.0, 1.0, 1.0), accumcol);\n		accumcol.a = vertexcolour.a;\n		return accumcol;\n	}\n	else\n	{\n		return vertexcolour;\n	}\n}\n\n#define _YY_GLSLES_ 1\n// Pass-through vertex shader (GameMaker's default)\nattribute vec3 in_Position;\nattribute vec4 in_Colour;\nattribute vec2 in_TextureCoord;\n\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nvoid main()\n{\n    gl_Position = gm_Matrices[MATRIX_WORLD_VIEW_PROJECTION] * vec4(in_Position, 1.0);\n    v_vColour = in_Colour;\n    v_vTexcoord = in_TextureCoord;\n}\n",
_y2:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n// Recolours a sprite and can outline it, for the monster ranks: hue shift (or a set hue), saturation and value multipliers, an optional berserk tint, and an outline in a given colour.\n// Draw with obj_unit's Draw (shd_white takes over while the unit flashes from a hit).\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform vec3 u_hsv;      // x: hue shift in turns (1.0 = 360 degrees), y: saturation multiplier, z: value multiplier\nuniform vec4 u_outline;  // rgb: outline colour, a: strength (0 = no outline)\nuniform vec2 u_texel;    // one texel of the sprite's texture page: 1/width, 1/height (texture_get_texel_width / height)\nuniform vec4 u_tint;     // rgb: colour mixed over the body, a: amount (the berserk pulse)\nuniform vec2 u_sethue;   // x: a hue (turns) that every coloured pixel takes instead of shifting, y: 1 = on (an elemental monster wears its element's hue)\n\nvec3 rgb2hsv(vec3 c)\n{\n    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);\n    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));\n    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));\n    float d = q.x - min(q.w, q.y);\n    float e = 0.0001;\n    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);\n}\n\nvec3 hsv2rgb(vec3 c)\n{\n    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);\n    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);\n    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);\n}\n\nvoid main()\n{\n    vec4 tex = texture2D(gm_BaseTexture, v_vTexcoord);\n    vec3 hsv = rgb2hsv(tex.rgb);\n    hsv.x = (u_sethue.y > 0.5 && hsv.y > 0.08) ? u_sethue.x : fract(hsv.x + u_hsv.x);   // greys and whites keep their hue (none)\n    hsv.y = clamp(hsv.y * u_hsv.y, 0.0, 1.0);\n    hsv.z = clamp(hsv.z * u_hsv.z, 0.0, 1.0);\n    vec3 rgb = mix(hsv2rgb(hsv), u_tint.rgb, u_tint.a);\n    vec4 body = vec4(rgb, tex.a) * v_vColour;\n\n    // outline: a transparent texel next to the sprite (1 and 2 texels away, 4 directions plus the diagonals) takes the outline colour\n    vec2 dx = vec2(u_texel.x, 0.0);\n    vec2 dy = vec2(0.0, u_texel.y);\n    float n = texture2D(gm_BaseTexture, v_vTexcoord + dx).a + texture2D(gm_BaseTexture, v_vTexcoord - dx).a\n            + texture2D(gm_BaseTexture, v_vTexcoord + dy).a + texture2D(gm_BaseTexture, v_vTexcoord - dy).a\n            + texture2D(gm_BaseTexture, v_vTexcoord + dx * 2.0).a + texture2D(gm_BaseTexture, v_vTexcoord - dx * 2.0).a\n            + texture2D(gm_BaseTexture, v_vTexcoord + dy * 2.0).a + texture2D(gm_BaseTexture, v_vTexcoord - dy * 2.0).a\n            + texture2D(gm_BaseTexture, v_vTexcoord + dx + dy).a + texture2D(gm_BaseTexture, v_vTexcoord - dx + dy).a\n            + texture2D(gm_BaseTexture, v_vTexcoord + dx - dy).a + texture2D(gm_BaseTexture, v_vTexcoord - dx - dy).a;\n    float oa = u_outline.a * clamp(n, 0.0, 1.0) * (1.0 - tex.a);\n    vec4 ring = vec4(u_outline.rgb, oa * v_vColour.a);\n\n    gl_FragColor = mix(ring, body, tex.a);\n}\n",
